const id = String($json.post_id ?? '').trim();
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(id)) throw new Error('Geçersiz Post ID');
return [{ json: { post_id: id } }];

if (!$json.id) throw new Error('Bu Post ID ile eşleşen gönderi bulunamadı');
const esc = (value) => String(value ?? '').replace(/[&<>\"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', "'": '&#39;' }[char]));
const hashtags = Array.isArray($json.hashtags) ? $json.hashtags.join(' ') : String($json.hashtags ?? '');
const imageUrl = `http://127.0.0.1:8080/generated/${encodeURIComponent($json.id)}.png`;
const previewHtml = `<article style="font-family:Arial,sans-serif;color:#13213c"><h2 style="margin-bottom:8px">${esc($json.hook)}</h2><div style="white-space:pre-wrap;line-height:1.55;margin-bottom:16px">${esc($json.body)}</div><p style="font-weight:600">${esc($json.cta)}</p><p style="color:#1769aa">${esc(hashtags)}</p><img src="${imageUrl}" alt="Gönderi görseli" style="display:block;width:100%;max-width:720px;height:auto;border-radius:12px;margin:20px auto;border:1px solid #dbe4f0"><p style="font-size:12px;color:#667085">Post ID: ${esc($json.id)} · Durum: ${esc($json.approval_status)}</p></article>`;
return [{ json: { ...$json, preview_html: previewHtml } }];

const id = String($json.post_id ?? '').trim();
const decisionMap = { 'Onayla': 'approved', 'Revizyon iste': 'needs_review', 'Reddet': 'rejected' };
const decision = decisionMap[String($json.decision ?? '').trim()];
const confirmed = Array.isArray($json.confirmed) ? $json.confirmed.includes('EVET') : String($json.confirmed).includes('EVET');
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(id)) throw new Error('Geçersiz Post ID');
if (!decision) throw new Error('Geçersiz karar');
if (!confirmed) throw new Error('Kontrol onay kutusu işaretlenmelidir');
return [{ json: { post_id: id, decision, reviewer_notes: String($json.reviewer_notes ?? '').trim() } }];
